from pathlib import Path
import pandas as pd

# Load files generated by run()
raw = pd.read_csv("data/Darknet.csv")
clean = pd.read_csv("outputs/processed/darknet_clean.csv")
quarantine = pd.read_csv("outputs/processed/quarantine.csv")
summary = pd.read_csv("outputs/reports/before_after_summary.csv")

print("=== AUTOMATED TEST & VERIFICATION REPORT ===")

# Test 1: Record Reconciliation
raw_n = len(raw)
clean_n = len(clean)
quar_n = len(quarantine)
assert (
    raw_n == clean_n + quar_n
), f"Mismatch! Raw ({raw_n}) != Clean ({clean_n}) + Quar ({quar_n})"
print(
    f"1. Reconciliation Test: PASSED (Raw {raw_n} = Clean {clean_n} + Quarantine {quar_n})"
)

# Test 2: Chart/Table Total Agreement
table_vol = pd.read_csv("outputs/reports/table_volume_over_time.csv")
assert (
    table_vol["events"].sum() == clean_n
), "Volume table sum does not match clean dataset count!"
print(
    f"2. Chart/Table Agreement Test: PASSED (Summary events {table_vol['events'].sum()} == Clean count {clean_n})"
)

# Test 3: Sensitive Identifier Audit
has_raw_ips = any(
    col in clean.columns for col in ["SourceIP", "Prefix", "RDNS"]
)
assert not has_raw_ips, "Raw IP columns found in clean output!"
print(
    "3. Privacy Disclosure Test: PASSED (0 raw IP/Prefix/RDNS columns present in clean CSV)"
)

# Test 4: Quarantine Transparency
print("\nQuarantine Reasons Summary:")
print(quarantine["reason"].value_counts().to_string())